function weightedScore(option, weights) {
  return Object.keys(weights).reduce(
    (total, criterion) => total + option.scores[criterion] * weights[criterion],
    0,
  );
}

function winningName(options, weights) {
  return options
    .map((option) => ({ name: option.name, score: weightedScore(option, weights) }))
    .sort((a, b) => b.score - a.score)[0].name;
}

function winnerHoldsAcrossAll(options, weightSets) {
  const winners = weightSets.map(({ weights }) => winningName(options, weights));
  return winners.every((name) => name === winners[0]);
}
